   150	        if (userToInvite) {
   151	            sectionsList.push({
   152	                title: '',
   153	                data: [userToInvite],
   154	                shouldShow: true,
   155	            });
   156	        }
   157	
   158	        return sectionsList.map((section) => ({
   159	            ...section,
